def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    if not hasattr(value, "total_seconds"):
        return None
    try:
        total = value.total_seconds()
        # Return an int if the total seconds is an integer value
        if isinstance(total, float) and total.is_integer():
            return int(total)
        return total
    except Exception:
        return None

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: The time value to dehydrate.
    :type value: datetime.time
    :return: ISO formatted string representation of the time, or None if value is None.
    """
    if value is None:
        return None
    try:
        import datetime
    except Exception as exc:
        raise RuntimeError("datetime module is required for dehydrate_time") from exc
    if not isinstance(value, datetime.time):
        raise TypeError(f"Expected datetime.time instance, got {type(value).__name__}")
    try:
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        # Attempt to extract latitude, longitude and time from the Point instance.
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time = getattr(value, 'time')
        # Convert datetime to ISO format if possible.
        if hasattr(time, 'isoformat'):
            time_str = time.isoformat()
        else:
            time_str = str(time)
        return {'lat': lat, 'lon': lon, 'time': time_str}
    except Exception as exc:
        raise ValueError(f"Unable to dehydrate Point: {exc}") from exc

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    try:
        # Try to get the underlying record structure
        record = getattr(self, "_record", None)
        if record is None:
            record = getattr(self, "record", None)

        # If it's a dictionary, return its keys
        if isinstance(record, dict):
            return list(record.keys())

        # If it's a list of dictionaries, return keys from the first element
        if isinstance(record, list) and record:
            first = record[0]
            if isinstance(first, dict):
                return list(first.keys())

        # Fallback: attempt to iterate over the record directly
        if record is not None:
            return [k for k in record]
    except Exception:
        # Any unexpected error results in an empty list
        return []

    # Default to an empty list if no record was found
    return []

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f'Key not found: {key}')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Retrieve all key/value pairs in order
    try:
        items = list(self.items())
    except AttributeError:
        try:
            items = list(self._items)
        except AttributeError:
            raise AttributeError("Object does not provide items() or _items for value extraction")

    # If no keys specified, return all values
    if not keys:
        return [value for _, value in items]

    # Prepare a list of all values for index-based access
    all_values = [value for _, value in items]
    result = []

    for key in keys:
        if isinstance(key, int):
            try:
                result.append(all_values[key])
            except IndexError:
                raise IndexError(f"Index {key} is out of range for the values list")
        elif isinstance(key, str):
            try:
                result.append(self[key])
            except KeyError:
                raise KeyError(f"Key '{key}' not found in the record")
        else:
            raise TypeError(f"Key must be an int or str, got {type(key).__name__}")

    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the key list and value list
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record must have _keys and _values attributes")
    keys_list = self._keys
    values_list = self._values

    # If _keys is a dict mapping key->index, create reverse mapping
    if isinstance(keys_list, dict):
        index_to_key = {idx: key for key, idx in keys_list.items()}
        key_to_index = keys_list
    else:
        # Assume list or tuple of keys
        index_to_key = {i: key for i, key in enumerate(keys_list)}
        key_to_index = {key: i for i, key in enumerate(keys_list)}

    # Helper to get value by index
    def _get_by_index(idx):
        if idx < -len(values_list) or idx >= len(values_list):
            raise IndexError(f"Index {idx} out of bounds")
        key_name = index_to_key[idx]
        return key_name, values_list[idx]

    # If no keys specified, return all
    if not keys:
        return {key: values_list[i] for i, key in enumerate(keys_list)}

    result = {}
    for k in keys:
        if isinstance(k, int):
            key_name, val = _get_by_index(k)
            result[key_name] = val
        elif isinstance(k, str):
            if k in key_to_index:
                idx = key_to_index[k]
                result[k] = values_list[idx]
            else:
                # key not present in record
                result[k] = None
        else:
            raise TypeError(f"Unsupported key type: {type(k).__name__}")
    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is None:
            mode = "WRITE"
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")
        # Validate bookmarks
        if bookmarks is not None:
            try:
                iter(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable")
            bookmarks = list(bookmarks)
        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict")
        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number")
        # Validate db
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string")
        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string")
        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            for t, fn in dehydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"dehydration hook for {t} is not callable")
        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            for t, fn in hydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"hydration hook for {t} is not callable")
        # Build the BEGIN message
        message = {"type": "BEGIN", "mode": mode}
        if bookmarks:
            message["bookmarks"] = bookmarks
        if metadata:
            message["metadata"] = metadata
        if timeout is not None:
            message["timeout"] = timeout
        if db is not None:
            message["db"] = db
        if imp_user is not None:
            message["imp_user"] = imp_user
        # Store hooks if provided
        if dehydration_hooks:
            self._dehydration_hooks = dehydration_hooks
        if hydration_hooks:
            self._hydration_hooks = hydration_hooks
        # Append the message to the output queue
        self._output_queue.append(message)
        # Return a Response object that will handle the server reply
        return Response(self, handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    seen = set()
    annotations = {}
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        if f in seen:
            raise TypeError(f"Duplicate field name: {f!r}")
        seen.add(f)
        annotations[f] = 'typing.Any'
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    namespace = {'__annotations__': annotations, '_srid_map': srid_map}
    def __init__(self, x, y, srid=None, **kwargs):
        Point.__init__(self, x, y, srid=srid)
        for key, value in kwargs.items():
            if key not in annotations:
                raise TypeError(f"Unexpected field {key!r}")
            setattr(self, key, value)
    namespace['__init__'] = __init__
    cls = type(name, (Point,), namespace)
    return cls

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    import re
    parts = re.split(r'\D+', s)
    nums = []
    for part in parts:
        if part:
            try:
                nums.append(int(part))
            except ValueError:
                continue
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}

        def make_key(args, kwargs):
            if typed:
                return (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(v) for v in args),
                    tuple(type(v) for v in kwargs.values()),
                )
            return (args, tuple(sorted(kwargs.items())))

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1
            if maxsize and len(cache) > maxsize:
                # Evict least frequently used key
                min_freq = min(freq.values())
                # Find first key with min_freq
                for k in list(freq):
                    if freq[k] == min_freq:
                        del cache[k]
                        del freq[k]
                        break
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Get the first key in insertion order
        first_key = next(iter(self))
        # Remove and return its value
        value = self.pop(first_key)
        return (first_key, value)
    except StopIteration:
        # The container is empty
        raise KeyError('dict is empty')

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    storage = self.storage
    try:
        if key in storage:
            return storage[key]
        storage[key] = default
        # Mark the storage as changed if it supports persistence
        if hasattr(storage, "_p_changed"):
            storage._p_changed = True
        return default
    except Exception as exc:
        logger.error(f"setdefault: Failed to set default for key {key!r}: {exc}")
        raise

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key is not hashable or other type error
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def is_file_exist(file_name):
    """Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
