def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.setLevel(logging.WARNING)
        stream_handler = logging.StreamHandler()
        stream_handler.setLevel(logging.WARNING)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        stream_handler.setFormatter(formatter)
        root.addHandler(stream_handler)
    except Exception as e:
        try:
            logging.getLogger().error("Failed to reset logging: %s", e)
        except Exception:
            pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls = self.__class__
    name = cls.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            name = name[:-len(suffix)]
            break
    try:
        module = __import__(cls.__module__, fromlist=[name])
        return getattr(module, name)
    except (ImportError, AttributeError):
        return cls

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        decl = getattr(object, "__provides__", None)
    except Exception:
        # If the object does not support attribute access, return an empty declaration
        return ()
    if decl is None:
        # No interfaces declared; return an empty declaration
        return ()
    return decl

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    # Validate that all elements are classes
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"element {cls!r} is not a class")
    # Find all classes that are superclasses of any other class in the list
    superclasses = set()
    n = len(classes)
    for i in range(n):
        cls = classes[i]
        for j in range(i + 1, n):
            other = classes[j]
            if issubclass(other, cls):
                superclasses.add(cls)
    # Build the minimal ordered list, removing duplicates
    seen = set()
    result = []
    for cls in classes:
        if cls in superclasses:
            continue
        if cls in seen:
            continue
        seen.add(cls)
        result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    result = []
    if all:
        names = dir(self)
    else:
        names = [k for k in self.__class__.__dict__ if not k.startswith('_')]
    for name in names:
        try:
            attr = getattr(self, name)
        except Exception:
            continue
        desc = None
        # Handle property
        if isinstance(attr, property):
            fget = attr.fget
            if fget and fget.__doc__:
                desc = fget.__doc__.strip()
        # Handle method or function
        elif callable(attr) and getattr(attr, "__doc__", None):
            desc = attr.__doc__.strip()
        # Handle other attributes: try class attribute docstring
        else:
            class_attr = self.__class__.__dict__.get(name)
            if class_attr and getattr(class_attr, "__doc__", None):
                desc = class_attr.__doc__.strip()
        result.append((name, desc))
    return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle broken interfaces
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except Exception:
        # If sequence has no __bases__ or Broken is not defined, ignore
        pass

    # Determine the class of the sequence
    try:
        cls = sequence.__class__
    except Exception:
        # If sequence has no __class__, treat it as a single item
        output.append(sequence)
        return output

    # Check if the sequence is an interface or implements spec
    try:
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
        else:
            # Assume the sequence is iterable and recurse
            for v in sequence:
                _normalizeargs(v, output)
    except Exception:
        # If the sequence is not iterable, treat it as a single item
        output.append(sequence)

    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    try:
        self.context = {}
    except AttributeError as exc:
        raise AttributeError("The histogram object does not have a 'context' attribute.") from exc

    # Reinitialize bins
    try:
        # If an explicit initial value is provided, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Ensure the initial value is numeric
            if not isinstance(self.initial_value, (int, float)):
                raise TypeError("initial_value must be a numeric type (int or float).")

            # If bins already exist, preserve their length
            if hasattr(self, "bins") and self.bins is not None:
                # Handle list or array-like bins
                if isinstance(self.bins, list):
                    self.bins = [self.initial_value for _ in self.bins]
                else:
                    # Try to use numpy for array-like objects
                    try:
                        import numpy as np
                        self.bins = np.full_like(self.bins, self.initial_value)
                    except Exception:
                        # Fallback to list conversion
                        self.bins = [self.initial_value for _ in self.bins]
            else:
                # No existing bins; create an empty list (length will be set later)
                self.bins = []

        # If no initial value, use the make_bins method
        else:
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError("The histogram object does not have a callable 'make_bins' method.")
    except Exception as exc:
        raise RuntimeError(f"Failed to reinitialize histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Ensure separator is a string
    separator = "" if separator is None else str(separator)
    lines = []

    # Add header if provided
    if header is not None:
        lines.append(str(header))

    # Iterate over points in the graph
    try:
        for point in self:
            # Try to unpack point into (coords, value)
            try:
                coords, value = point
            except Exception:
                # Fallback: try attributes
                try:
                    coords = getattr(point, "coords", None)
                    value = getattr(point, "value", None)
                except Exception:
                    # Skip points that cannot be processed
                    continue

            # Convert coordinates to a string
            if coords is None:
                coord_str = ""
            else:
                try:
                    coord_str = separator.join(map(str, coords))
                except Exception:
                    coord_str = str(coords)

            # Convert value parts
            parts = []
            if value is None:
                parts = []
            else:
                # Treat strings as scalars
                if isinstance(value, str):
                    parts = [value]
                else:
                    # Try to iterate over value
                    try:
                        # Avoid treating bytes as iterable of ints
                        if isinstance(value, (bytes, bytearray)):
                            parts = [str(value)]
                        else:
                            parts = [str(v) for v in value]
                    except TypeError:
                        parts = [str(value)]

            # Build the CSV line
            line = separator.join([coord_str] + parts)
            lines.append(line)
    except Exception as exc:
        raise RuntimeError(f"Error converting graph to CSV: {exc}") from exc

    # Join all lines with newline characters
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    if not hasattr(self, "_errors"):
        raise AttributeError("Object has no _errors attribute")
    if coord_name not in self._errors:
        raise KeyError(f"Coordinate {coord_name!r} not found in errors")
    err = self._errors[coord_name]
    if err is None:
        return np.array([], dtype=int)
    try:
        arr = np.asarray(err)
    except Exception as exc:
        raise ValueError(f"Error array for {coord_name!r} could not be converted to array") from exc
    if arr.ndim != 1:
        raise ValueError(f"Error array for {coord_name!r} must be 1-D, got {arr.ndim}-D")
    if arr.size == 0:
        return np.array([], dtype=int)
    mask = ~np.isnan(arr) & (arr != 0)
    return np.where(mask)[0]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Exclude Source sequences
        if isinstance(seq, Source):
            return False
        # Direct FillRequest instance
        if isinstance(seq, FillRequest):
            return True
        # Iterable check (exclude strings/bytes)
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
            for item in seq:
                if isinstance(item, FillRequest):
                    return True
            return False
        return False
    except Exception:
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (hasattr(obj, 'fill') and callable(getattr(obj, 'fill')) and
                hasattr(obj, 'request') and callable(getattr(obj, 'request')))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
        return callable(run_attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "compute", None))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")

    # If d2 is empty, the difference is d1 itself (may return directly)
    if not d2:
        return d1

    # If d1 is empty, the difference is empty
    if not d1:
        return {}

    # Helper to decide recursion depth
    def _next_level(cur_level):
        if cur_level == -1:
            return -1
        if cur_level > 0:
            return cur_level - 1
        return 0  # level 0 means no recursion

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key only in d1
            result[key] = val1
        else:
            val2 = d2[key]
            # Both values are dicts and we can recurse
            if isinstance(val1, dict) and isinstance(val2, dict):
                if level == 0:
                    # No recursion: treat as values
                    if val1 != val2:
                        result[key] = val1
                else:
                    sublevel = _next_level(level)
                    subdiff = difference(val1, val2, sublevel)
                    if subdiff:
                        result[key] = subdiff
            else:
                # At least one is not a dict; compare directly
                if val1 != val2:
                    result[key] = val1

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception as exc:
        raise TypeError("weight must be a numeric scalar") from exc

    # Ensure histogram has edges and bins
    if not hasattr(self, 'edges') or self.edges is None:
        raise AttributeError("Histogram has no edges defined")
    if not hasattr(self, 'bins') or self.bins is None:
        raise AttributeError("Histogram has no bins defined")

    # Normalize edges to a list of 1D arrays
    if isinstance(self.edges, (list, tuple)):
        edges = list(self.edges)
    else:
        edges = [self.edges]

    # Convert coord to array
    try:
        coord_arr = np.asarray(coord)
    except Exception as exc:
        raise TypeError("coord must be array-like") from exc

    # Handle scalar coord for 1D histogram
    if coord_arr.ndim == 0:
        coord_arr = coord_arr.reshape(1)

    # Check dimensionality
    if coord_arr.shape[0] != len(edges):
        raise ValueError(f"coord must have {len(edges)} elements, got {coord_arr.shape[0]}")

    # Find bin indices
    idx = []
    for dim, edge in enumerate(edges):
        # Ensure edge is 1D array
        edge_arr = np.asarray(edge)
        if edge_arr.ndim != 1:
            raise ValueError(f"edge for dimension {dim} must be 1D")
        # Find bin index
        i = np.searchsorted(edge_arr, coord_arr[dim], side='right') - 1
        if i < 0 or i >= len(edge_arr) - 1:
            # Coordinate outside histogram bounds; ignore
            return
        idx.append(i)

    # Increment the appropriate bin
    try:
        self.bins[tuple(idx)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to increment histogram bin") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    # Define simple regex patterns for keys and values.
    # Adjust these patterns to match the actual requirements.
    key_regex = re.compile(r'^[a-zA-Z0-9_-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_-]+$')

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not key_regex.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value(s)
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(item):
                        errors.append({item: f"Label value '{item}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_regex.match(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")
    pattern = r'^[A-Za-z0-9_-]{8,32}$'
    try:
        if not re.fullmatch(pattern, key):
            raise ValidationError(f"Key '{key}' does not match required pattern")
    except NameError:
        raise ValidationError("Regex module not available")
    except Exception as exc:
        raise ValidationError(f"Error validating key: {exc}")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if app is None:
            raise ValueError("app cannot be None")

        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("app has no 'spec' attribute")

        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("spec has no 'manifest' attribute")

        if not isinstance(manifest, (list, tuple)):
            raise TypeError("spec.manifest must be a list or tuple")

        observer_schema = getattr(spec, "observer_schema", None)
        if observer_schema is None:
            observer_schema = {}
            setattr(spec, "observer_schema", observer_schema)
        elif not isinstance(observer_schema, dict):
            raise TypeError("spec.observer_schema must be a dict if present")

        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            if kind not in observer_schema:
                # Default schema includes metadata and status sections
                default_schema = {
                    "metadata": {
                        "type": "object",
                        "properties": {
                            "name": {"type": "string"},
                            "namespace": {"type": "string"},
                        },
                    },
                    "status": {"type": "object"},
                }
                observer_schema[kind] = default_schema

        return observer_schema
    except Exception as exc:
        raise ValueError(f"Failed to generate default observer schema: {exc}") from exc

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    if hasattr(status, 'name'):
        status_str = status.name
    else:
        status_str = str(status)
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Retrieve the log; fall back to an empty list if not present
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, 'validation_log', [])
    if not isinstance(log, (list, tuple)):
        raise TypeError("validation log must be a list or tuple")
    lines = []
    for entry in log:
        try:
            if isinstance(entry, dict):
                # Prefer a 'message' key, otherwise stringify the dict
                msg = entry.get('message', str(entry))
            else:
                msg = str(entry)
        except Exception:
            # If entry cannot be converted to string, skip it
            continue
        lines.append(f"{prefix}{msg}")
    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None or digests_used is None:
        raise ValueError("Both manifest_files and digests_used must be provided")

    # Ensure manifest_files is a mapping of filenames to digests
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")

    # Ensure digests_used is an iterable of digests
    try:
        digests_used_set = set(digests_used)
    except TypeError:
        raise TypeError("digests_used must be an iterable of digests")

    manifest_digests = set(manifest_files.values())

    # Digests that are required by the manifest but not used
    missing = manifest_digests - digests_used_set
    if missing:
        raise ValueError(f"Missing digests that are required by the manifest: {missing}")

    # Digests that are used but not present in the manifest
    unused = digests_used_set - manifest_digests
    if unused:
        raise ValueError(f"Digests used but not present in the manifest: {unused}")

    # If we reach here, all required digests are present and used
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        raise TypeError("prior must not be None")

    # Ensure prior has the expected attributes
    required_attrs = ['species', 'parameters', 'stoichiometry_matrix',
                      'propensities', 'constraints']
    for attr in required_attrs:
        if not hasattr(prior, attr):
            raise TypeError(f"prior must have attribute '{attr}'")

    # Check that species lists match
    if set(prior.species) != set(self.species):
        raise ValueError("Species mismatch between current inventory and prior")

    # Check that parameters lists match
    if set(prior.parameters) != set(self.parameters):
        raise ValueError("Parameters mismatch between current inventory and prior")

    # Check stoichiometry matrix shape
    try:
        s_rows, s_cols = prior.stoichiometry_matrix.rows, prior.stoichiometry_matrix.cols
        self_s_rows, self_s_cols = self.stoichiometry_matrix.rows, self.stoichiometry_matrix.cols
    except Exception as exc:
        raise ValueError(f"Error accessing stoichiometry matrix dimensions: {exc}") from exc
    if s_rows != self_s_rows or s_cols != self_s_cols:
        raise ValueError("Stoichiometry matrix shape mismatch between current inventory and prior")

    # Check propensities shape
    try:
        p_rows, p_cols = prior.propensities.rows, prior.propensities.cols
        self_p_rows, self_p_cols = self.propensities.rows, self.propensities.cols
    except Exception as exc:
        raise ValueError(f"Error accessing propensities dimensions: {exc}") from exc
    if p_rows != self_p_rows or p_cols != self_p_cols:
        raise ValueError("Propensities shape mismatch between current inventory and prior")

    # Check constraints keys
    if set(prior.constraints.keys()) != set(self.constraints.keys()):
        raise ValueError("Constraints mismatch between current inventory and prior")

    # All checks passed
    return None

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None or not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping logical paths to versioned file sets")
    if version is None:
        raise ValueError("version must be specified")

    # Helper to compare versions; fallback to string comparison if parsing fails
    def _compare_versions(v1, v2):
        try:
            # Attempt numeric comparison if possible
            parts1 = [int(p) if p.isdigit() else p for p in v1.replace('-', '.').split('.')]
            parts2 = [int(p) if p.isdigit() else p for p in v2.replace('-', '.').split('.')]
            return (parts1 > parts2) - (parts1 < parts2)
        except Exception:
            return (v1 > v2) - (v1 < v2)

    result = {}
    for logical_path, version_map in inventory.items():
        if not isinstance(version_map, dict):
            # If the value is not a dict, skip or treat as single entry
            continue
        content_set = set()
        for ver, files in version_map.items():
            if not isinstance(files, (set, list)):
                continue
            try:
                cmp = _compare_versions(ver, version)
            except Exception:
                # If comparison fails, skip this entry
                continue
            if cmp == 0 or cmp > 0:
                # Include files for the exact version or later versions
                content_set.update(files)
        if content_set:
            result[logical_path] = content_set
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set, list, or tuple")

    # Ensure the required top-level key exists
    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")

    manifest_set = set(manifest_files)
    seen_paths = set()

    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")

        # Required keys for each file entry
        for key in ('path', 'hash', 'size'):
            if key not in entry:
                raise ValueError(f"File entry at index {idx} missing required key: '{key}'")

        path = entry['path']
        hash_val = entry['hash']
        size = entry['size']

        if not isinstance(path, str):
            raise ValueError(f"File path at index {idx} must be a string")
        if not isinstance(hash_val, str):
            raise ValueError(f"Hash for file '{path}' must be a string")
        if not isinstance(size, int):
            raise ValueError(f"Size for file '{path}' must be an integer")

        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity not found in manifest")

        if path in seen_paths:
            raise ValueError(f"Duplicate file path in fixity: '{path}'")
        seen_paths.add(path)

    return True

def files_list(path):
    """Return the files in `path`"""
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        files = []
        for root, dirs, filenames in os.walk(path):
            for f in filenames:
                files.append(os.path.abspath(os.path.join(root, f)))
        return files
    raise FileNotFoundError(f"Path is neither file nor directory: {path}")

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    data = {}
    try:
        if not os.path.isdir(folder):
            return {}
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                base, ext = os.path.splitext(entry)
                # Use the base name of the XML file as the key
                key = base
                data.setdefault(key, []).append(full_path)
    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}
    return data

def add_asset(self, basename, file_path):
    """
    {
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Validate input types
    if not isinstance(basename, str) or not isinstance(file_path, str):
        raise TypeError("basename and file_path must be strings")
    # Ensure the file exists
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")
    try:
        # Obtain the repository manager
        mgr = self._get_provider_manager('REPOSITORY')
        # Create a form for a new asset
        create_form = self.get_asset_form_for_create()
        # Set the asset name
        if hasattr(create_form, 'set_name'):
            create_form.set_name(basename)
        else:
            raise AttributeError("Asset form does not support setting a name")
        # Attach the file to the form; the exact method may vary
        if hasattr(create_form, 'set_file_path'):
            create_form.set_file_path(file_path)
        elif hasattr(create_form, 'set_file'):
            create_form.set_file(file_path)
        else:
            raise AttributeError("Asset form does not support setting a file")
        # Create the asset
        asset = self.create_asset(create_form)
        # Return the new asset's ID
        return asset.get_id()
    except Exception as e:
        raise RuntimeError(f"Failed to add asset '{basename}' from '{file_path}': {e}") from e

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: find all XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(base)

            # Second pass: group files by those basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base not in xml_basenames:
                    continue
                content = zf.read(info)
                if base not in result:
                    result[base] = {}
                result[base][info.filename] = content
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    return result

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Filter out directory entries and return a sorted list
            return sorted([name for name in zf.namelist() if not name.endswith('/')])
    except Exception:
        # If the file cannot be opened as a zip or any other error occurs,
        # return an empty list to indicate no files were found.
        return []

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError("Error processing content") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent
    try:
        if not isinstance(indent, int):
            raise TypeError("indent must be an integer")
        if indent < 0:
            raise ValueError("indent must be non-negative")
    except Exception:
        indent = 0
    # Validate debug
    try:
        debug = bool(debug)
    except Exception:
        debug = False
    # Format representation
    try:
        import pprint
        formatted = pprint.pformat(self, indent=indent)
    except Exception:
        try:
            formatted = repr(self)
        except Exception:
            formatted = str(self)
    # Add debug info if requested
    if debug:
        try:
            header = f"{type(self).__name__} at {hex(id(self))}\n"
            return header + formatted
        except Exception:
            return formatted
    return formatted

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("hook must not be None")
    def decorator(fn):
        if not callable(fn):
            raise TypeError("handler must be callable")
        try:
            self.register_hook(hook, fn)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from exc
        return fn
    return decorator

def _fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt.tzinfo is not self:
        raise ValueError("dt.tzinfo must be the same as self")
    # dt is UTC
    try:
        # If the tzinfo provides a localize method (pytz), use it
        if hasattr(self, "localize"):
            # Remove tzinfo to get naive datetime
            naive = dt.replace(tzinfo=None)
            # Determine if ambiguous
            if hasattr(self, "is_ambiguous") and self.is_ambiguous(naive):
                # Use fold attribute to decide which side
                fold = getattr(dt, "fold", 0)
                is_dst = fold == 0
                return self.localize(naive, is_dst=is_dst)
            else:
                return self.localize(naive, is_dst=None)
        else:
            # Fallback to astimezone
            return dt.astimezone(self)
    except Exception as exc:
        raise ValueError("Failed to convert datetime") from exc

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if PY3:
            return result
        else:
            try:
                return result.encode()
            except Exception as e:
                raise ValueError("Result of namefunc cannot be encoded to bytes: %s" % e)
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        with open('version.py', 'r') as f:
            contents = f.read()
        for line in contents.splitlines():
            if '__version__' in line:
                try:
                    _, val = line.split('=', 1)
                    val = val.strip().strip('\'"')
                    if val:
                        return val
                except ValueError:
                    continue
        return default
    except Exception:
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if pieces is None:
        raise ValueError("pieces cannot be None")
    # If pieces is a string, treat it as a single piece
    if isinstance(pieces, str):
        pieces = [pieces]
    # Ensure pieces is iterable
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of strings or objects")
    # Convert each piece to a string safely
    rendered_pieces = []
    for p in pieces:
        try:
            rendered_pieces.append(str(p))
        except Exception:
            rendered_pieces.append(repr(p))
    # Default style
    if style is None:
        style = 'plain'
    # Normalize style if it's a string
    if isinstance(style, str):
        style = style.lower()
    # Render according to style
    if style == 'plain':
        return '\n'.join(rendered_pieces)
    elif style == 'html':
        return ''.join(f'<p>{p}</p>' for p in rendered_pieces)
    elif style == 'markdown':
        return '\n\n'.join(rendered_pieces)
    elif callable(style):
        try:
            return style(rendered_pieces)
        except Exception as exc:
            raise RuntimeError("Error rendering with custom style function") from exc
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if '+' not in pieces:
            return '+'
        else:
            return '.'
    except Exception:
        raise ValueError("pieces must be an iterable containing '+' or not")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("commands cannot be None")
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a list or tuple of strings")
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    cmd = list(commands) + list(args)
    if verbose:
        print("Running command:", ' '.join(cmd))
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        output = subprocess.check_output(
            cmd,
            cwd=cwd,
            env=env,
            stderr=stderr,
            universal_newlines=True
        )
    except subprocess.CalledProcessError as e:
        raise
    except OSError as e:
        raise
    return output

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool')

    num_objects = 0
    good_objects = 0
    warnings = []

    # Attempt to retrieve all objects in the hierarchy
    try:
        objects = self._iter_objects()  # Expected to return an iterable of objects
    except AttributeError:
        # Fallback: try a common attribute name
        try:
            objects = getattr(self, 'objects', [])
        except Exception as exc:
            raise RuntimeError('Unable to retrieve objects for validation') from exc
    except Exception as exc:
        raise RuntimeError('Error retrieving objects for validation') from exc

    for obj in objects:
        num_objects += 1
        obj_valid = True
        try:
            # Validate the object itself if requested
            if validate_objects:
                if hasattr(obj, 'validate'):
                    if not obj.validate():
                        obj_valid = False
                elif hasattr(obj, 'is_valid'):
                    if not obj.is_valid():
                        obj_valid = False
                else:
                    # No known validation method; treat as invalid
                    obj_valid = False

            # Check digests if requested
            if check_digests:
                if hasattr(obj, 'compute_digest') and hasattr(obj, 'get_stored_digest'):
                    computed = obj.compute_digest()
                    stored = obj.get_stored_digest()
                    if computed != stored:
                        obj_valid = False
                else:
                    # No digest methods available; treat as invalid
                    obj_valid = False
        except Exception as exc:
            obj_valid = False
            warnings.append(f'Object {obj!r} raised exception during validation: {exc}')

        if obj_valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f'Warning: Object {obj!r} failed validation')
            warnings.append(f'Object {obj!r} failed validation')

    if show_warnings and warnings:
        for w in warnings:
            print(w)

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json
    import errno
    from datetime import datetime

    # The root path must be defined on the instance.
    root = getattr(self, "root_path", None)
    if not root:
        raise ValueError("Instance attribute 'root_path' is not set")

    # Create the root directory if it does not exist.
    try:
        os.makedirs(root, exist_ok=True)
    except OSError as exc:
        if exc.errno != errno.EEXIST:
            raise

    # The OCFL root marker file must not already exist.
    ocfl_root_file = os.path.join(root, ".ocfl_root")
    if os.path.exists(ocfl_root_file):
        raise FileExistsError(f"OCFL root already exists at {root}")

    # Write minimal OCFL metadata.
    metadata = {
        "ocfl_version": "1.0",
        "created_at": datetime.utcnow().isoformat() + "Z",
    }
    try:
        with open(ocfl_root_file, "w", encoding="utf-8") as f:
            json.dump(metadata, f, indent=2)
    except OSError as exc:
        raise IOError(f"Failed to write OCFL root file: {exc}") from exc

    # Create the objects directory.
    objects_dir = os.path.join(root, "objects")
    try:
        os.makedirs(objects_dir, exist_ok=True)
    except OSError as exc:
        raise IOError(f"Failed to create objects directory: {exc}") from exc

    # Store the root path on the instance for later use.
    self.root_path = root
    return root

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    original_len = len(version)
    try:
        new_num = int(version) + 1
    except Exception as exc:
        raise ValueError("invalid numeric value") from exc
    new_version = str(new_num).zfill(original_len)
    return new_version

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Helper to load an inventory file into a dict {path: digest}
    def _load_inventory(inv_path):
        inv = {}
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                for lineno, line in enumerate(fh, start=1):
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split(maxsplit=1)
                    if len(parts) != 2:
                        raise ValueError(
                            f"Malformed inventory line {lineno} in {inv_path}: {line!r}"
                        )
                    digest, path = parts
                    inv[path] = digest
        except OSError as exc:
            raise FileNotFoundError(f"Could not read inventory {inv_path}: {exc}") from exc
        return inv

    # Load root inventory
    root_inv_path = os.path.join(self.root_dir, self.inventory_file)
    root_inv = _load_inventory(root_inv_path)

    # Keep a cumulative inventory of all entries seen so far
    cumulative = dict(root_inv)

    # Record any digests that differ from the root inventory
    self.different_digests = {}

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(self.root_dir, vdir, self.inventory_file)
        inv = _load_inventory(inv_path)

        # Each version must contain all entries from previous versions
        missing = set(cumulative.keys()) - set(inv.keys())
        if missing:
            raise ValueError(
                f"Inventory for version {vdir} is missing entries: {sorted(missing)}"
            )

        # Update cumulative inventory
        cumulative.update(inv)

        # Compare digests to root inventory
        for path, digest in inv.items():
            root_digest = root_inv.get(path)
            if root_digest and root_digest != digest:
                self.different_digests.setdefault(path, []).append(
                    (vdir, digest, root_digest)
                )

    return self.different_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")

    # If no bug_ids provided, nothing to amend
    if bug_ids is None:
        return params

    # Helper to extract an id from various possible objects
    def _extract_id(item):
        if hasattr(item, "id"):
            return str(item.id)
        if isinstance(item, dict) and "id" in item:
            return str(item["id"])
        return str(item)

    # Build a set of ids to add
    ids_to_add = set()

    # Handle string input (comma or whitespace separated)
    if isinstance(bug_ids, str):
        parts = [p.strip() for p in bug_ids.replace(",", " ").split() if p.strip()]
        ids_to_add.update(parts)
    else:
        # Try to iterate over bug_ids; if not iterable treat as single id
        try:
            iterator = iter(bug_ids)
        except TypeError:
            ids_to_add.add(_extract_id(bug_ids))
        else:
            for item in iterator:
                ids_to_add.add(_extract_id(item))

    if not ids_to_add:
        return params

    # Merge with any existing 'ids' entry in params
    existing = params.get("ids")
    if existing:
        if isinstance(existing, str):
            existing_ids = [p.strip() for p in existing.replace(",", " ").split() if p.strip()]
        elif isinstance(existing, (list, tuple, set)):
            existing_ids = [str(p).strip() for p in existing if str(p).strip()]
        else:
            existing_ids = [str(existing).strip()]
        ids_to_add.update(existing_ids)

    # Store the combined ids as a comma‑separated string
    # Sort numerically if possible, otherwise lexicographically
    try:
        sorted_ids = sorted(ids_to_add, key=lambda x: int(x))
    except ValueError:
        sorted_ids = sorted(ids_to_add)
    params["ids"] = ",".join(sorted_ids)

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Basic validation
    if nodes is None:
        return []
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, value) tuples')
    # Helper to merge two values
    def merge_values(v1, v2):
        # If both are MappingNode, deep merge their contents
        try:
            from ruamel.yaml.nodes import MappingNode
        except Exception:
            MappingNode = None
        if MappingNode and isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            # Merge the mapping lists
            merged_list = deep_merge_nodes(v1.value + v2.value)
            # Preserve the tag from the first node
            return MappingNode(tag=v1.tag, value=merged_list)
        # Otherwise, last value wins
        return v2
    # Use ordered dict to preserve first occurrence order
    merged_dict = {}
    order = []
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('Each element of nodes must be a tuple of (ScalarNode, value)')
        key_node, value_node = entry
        # Use key value string for deduplication
        key_id = getattr(key_node, 'value', None)
        if key_id is None:
            raise ValueError('Key node must have a .value attribute')
        if key_id in merged_dict:
            # Merge existing value with new one
            merged_dict[key_id] = merge_values(merged_dict[key_id], value_node)
        else:
            merged_dict[key_id] = value_node
            order.append(key_id)
    # Build result list preserving order
    result = []
    for key_id in order:
        # Find the original key node (first occurrence)
        for entry in nodes:
            if getattr(entry[0], 'value', None) == key_id:
                key_node = entry[0]
                break
        else:
            # Should not happen
            continue
        result.append((key_node, merged_dict[key_id]))
    return result

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    parser = argparse.ArgumentParser(description='Script arguments')
    parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose output')
    parser.add_argument('-c', '--config', type=str, help='Path to configuration file')
    parser.add_argument('positional', nargs='*', help='Positional arguments')
    try:
        if arguments:
            # If a single list/tuple is passed, flatten it
            if len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
                args_list = list(arguments[0])
            else:
                args_list = list(arguments)
            return parser.parse_args(args_list)
        else:
            return parser.parse_args()
    except SystemExit as e:
        # argparse raises SystemExit on error; convert to RuntimeError for caller
        raise RuntimeError(f'Argument parsing failed: {e}') from e
    except Exception as e:
        raise RuntimeError(f'Unexpected error during argument parsing: {e}') from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation of the input
    if parser is None:
        raise ValueError("parser cannot be None")
    # argparse.ArgumentParser is the expected type; if argparse is not imported,
    # we fall back to checking for the presence of the _actions attribute.
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # Only include actions that have option strings (i.e., flags)
            if getattr(action, "option_strings", None):
                flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception as exc:
        # Wrap any unexpected errors in a RuntimeError for clarity
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        # option_strings is a list of flag strings (e.g., ['-h', '--help'])
        if hasattr(action, 'option_strings') and action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    try:
        parser = argparse.ArgumentParser()
        # Create a subparsers group; actual subparsers should be added by the caller before invoking this function
        parser.add_subparsers(dest='subparser_name', required=False)
        namespace = parser.parse_args(list(unparsed_arguments))
        result = {}
        sub_name = getattr(namespace, 'subparser_name', None)
        if sub_name:
            result[sub_name] = namespace
        else:
            result['global'] = namespace
        return result
    except SystemExit:
        # argparse throws SystemExit on parse errors; return an empty dict to indicate failure
        return {}
    except Exception:
        # Unexpected errors; return an empty dict to avoid crashing the caller
        return {}

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be greater than zero")
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("All items in the iterable must be dictionaries")
        for key, value in d.items():
            if key in result:
                existing = result[key]
                if isinstance(existing, (int, float)) and isinstance(value, (int, float)):
                    result[key] = existing + value
                else:
                    raise TypeError(f"Cannot sum non-numeric values for key '{key}'")
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not isinstance(url_args, dict):
        raise TypeError('url_args must be a dict')

    # Pattern to find placeholders like {key}
    pattern = re.compile(r'\{([^}]+)\}')

    def _replacer(match):
        key = match.group(1)
        if key in url_args:
            # Convert the value to string for URL substitution
            return str(url_args[key])
        # If key not found, leave placeholder unchanged
        return match.group(0)

    try:
        return pattern.sub(_replacer, url)
    except Exception as exc:
        # In case of unexpected errors, return original URL
        logger.warning('Failed to replace URL args: %s', exc)
        return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings are considered for "none" representations
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string is considered None-like
        if not stripped:
            return True
        # Common textual representations of None
        if stripped.lower() in {"none", "null", "undefined"}:
            return True
    return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        option_strings = getattr(action, "option_strings", [])
        for opt in option_strings:
            if isinstance(opt, str) and opt.startswith("-"):
                flags.append(opt)

    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single-character string")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        pad_len = padding - len(digits)
        digits = [alphabet[0]] * pad_len + digits

    return ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")

    for flow_name, flow_dict in flow_params.items():
        if not isinstance(flow_dict, dict):
            continue
        if register_value in flow_dict:
            flow_dict[register_value] = register_number

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if value is None:
        raise ValueError("value cannot be None")
    if arg is None:
        raise ValueError("arg cannot be None")
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        c = queue.pop()
        if c in seen:
            continue
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.append(sub)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if alphabet is None:
        raise ValueError("Alphabet must not be None.")
    if not isinstance(alphabet, (list, tuple)):
        # Accept any iterable and convert to list
        alphabet = list(alphabet)
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"Alphabet element at index {idx} is not a single character string.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate characters.")
    base = len(alphabet)

    # Build mapping from character to its numeric value
    digit_map = {ch: i for i, ch in enumerate(alphabet)}

    # Validate input string
    if string is None:
        raise ValueError("Input string must not be None.")
    if not isinstance(string, str):
        raise ValueError("Input string must be a string.")
    if string == "":
        raise ValueError("Input string must not be empty.")

    # Convert string to integer
    value = 0
    for pos, ch in enumerate(string):
        if ch not in digit_map:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet.")
        value = value * base + digit_map[ch]
    return value

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate input types
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    if not isinstance(destination_path, Path):
        raise TypeError(f"destination_path must be a pathlib.Path, got {type(destination_path).__name__}")

    # Ensure destination directory exists and is empty
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise OSError(f"Destination path {destination_path} exists and is not a directory")
            if any(destination_path.iterdir()):
                raise OSError(f"Destination directory {destination_path} is not empty")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to prepare destination directory {destination_path}: {exc}") from exc

    # Download the archive to a temporary file
    import tempfile
    import tarfile
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
            tmp_path = Path(tmp_file.name)
            try:
                with requests.get(url, stream=True, timeout=30) as resp:
                    resp.raise_for_status()
                    for chunk in resp.iter_content(chunk_size=8192):
                        if chunk:
                            tmp_file.write(chunk)
            except Exception as exc:
                raise RuntimeError(f"Failed to download archive from {url}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to create temporary file for download: {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(tmp_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive {tmp_path} to {destination_path}: {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            tmp_path.unlink()
        except Exception:
            pass

    return destination_path

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Strip leading and trailing single or double quotes
    return re.sub(r"^['\"]|['\"]$", "", name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if platform == 'this':
        import sys
        platform = 0 if sys.platform == 'win32' else 1
    if platform == 1:
        # POSIX splitting using regex
        pattern = r'''(?:"([^"]*)"|'([^']*)'|(\S+))'''
        parts = []
        for m in re.finditer(pattern, s):
            part = m.group(1) or m.group(2) or m.group(3)
            parts.append(part)
        return parts
    elif platform == 0:
        import shlex
        return shlex.split(s, posix=False)
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            universal_newlines=True
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
        if freq_str.lower() == "always":
            return None
        parts = freq_str.split()
        if len(parts) != 2:
            raise ValueError(f"Cannot parse frequency: {frequency}")
        num_str, unit = parts
        try:
            num = int(num_str)
        except ValueError:
            raise ValueError(f"Invalid number in frequency: {frequency}")
        unit = unit.lower()
        if unit in ('day', 'days'):
            return datetime.timedelta(days=num)
        elif unit in ('hour', 'hours'):
            return datetime.timedelta(hours=num)
        elif unit in ('minute', 'minutes'):
            return datetime.timedelta(minutes=num)
        elif unit in ('second', 'seconds'):
            return datetime.timedelta(seconds=num)
        elif unit in ('week', 'weeks'):
            return datetime.timedelta(weeks=num)
        elif unit in ('month', 'months'):
            return datetime.timedelta(days=num * 30)
        elif unit in ('year', 'years'):
            return datetime.timedelta(days=num * 365)
        else:
            raise ValueError(f"Unknown unit in frequency: {frequency}")
    else:
        raise ValueError(f"Frequency must be a string or None, got {type(frequency)}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        # Resolve the host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False

    for info in addrinfo:
        # info[4] is a tuple like (address, port) for IPv4 or (address, port, flowinfo, scopeid) for IPv6
        address = info[4][0]
        # IPv6 loopback
        if ':' in address:
            if address == '::1':
                return True
        # IPv4 loopback
        else:
            if address.startswith('127.'):
                return True
    return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract the variable name from the matcher
    try:
        name = matcher.name
    except AttributeError:
        try:
            name = matcher['name']
        except (TypeError, KeyError):
            try:
                name = matcher.group('name')
            except Exception:
                raise ValueError("Matcher does not contain a 'name' field")

    # Extract the optional default value from the matcher
    default = None
    try:
        default = matcher.default
    except AttributeError:
        try:
            default = matcher['default']
        except (TypeError, KeyError):
            try:
                default = matcher.group('default')
            except Exception:
                default = None

    # Retrieve the environment variable
    value = os.environ.get(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if pattern is None:
        raise TypeError("Pattern cannot be None")
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Determine the compiled regex type
    if hasattr(re, 'Pattern'):
        pattern_type = re.Pattern
    else:
        pattern_type = type(re.compile(''))
    if isinstance(pattern, pattern_type):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Use yaml.safe_dump which returns a unicode string on Python 2
        # and a str on Python 3. The optional dumper can override the
        # default SafeDumper if needed.
        return yaml.safe_dump(obj, Dumper=dumper)
    except Exception as exc:
        raise ValueError(f"Failed to dump object to string: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x)
        mean = 0.2
        sigma = 0.1
        coeff = 1.0/(sigma*np.sqrt(2*np.pi))
        exponent = -0.5 * ((x_arr - mean) / sigma) ** 2
        return coeff * np.exp(exponent)
    except Exception as e:
        raise ValueError(f"Invalid input for gaussian: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported config file type: {fname}")

            if overrides:
                cfg.update(overrides)

            if resolve_env:
                cfg = _expand_env(cfg)

            configs[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Error parsing config file {fname}: {e}",
                args=(),
                exc_info=e
            )
            errors.append(record)

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate protocol_version
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple of (major, minor)")
        if len(protocol_version) != 2 or not all(isinstance(v, int) for v in protocol_version):
            raise TypeError("protocol_version must be a tuple of two integers")

    # Retrieve handlers mapping
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(handlers)

    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

