def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a list or tuple of types")
    # If explicit metaclass is provided, use it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit __metaclass__ must be a type")
        return explicit_mc
    # If no bases, default to type
    if not bases:
        return type
    # Collect metaclasses of bases
    metaclasses = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a type")
        metaclasses.append(type(base))
    # Determine the most derived metaclass
    most_derived = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(most_derived, mc):
            # most_derived is more derived
            continue
        elif issubclass(mc, most_derived):
            most_derived = mc
        else:
            raise TypeError(f"metaclass conflict: {most_derived} and {mc}")
    return most_derived

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        return self._cache.popitem(last=False)
    except KeyError:
        raise KeyError('LRU cache is empty')

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self)
    except KeyError:
        raise KeyError('dict is empty')

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches an IN clause like "IN (value1, value2, ...)"
        # Captures the comma-separated values inside the parentheses.
        pattern = r'\bIN\s*\((?P<values>[^)]*)\)'
        return re.compile(pattern, flags=re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

