def default_tzinfo(dt, tzinfo):
    """Sets the ``tzinfo`` parameter on naive datetimes only.

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.

    :param dt: The datetime on which to replace the time zone.
    :param tzinfo: The :py:class:`datetime.tzinfo` subclass instance to assign
                   to ``dt`` if (and only if) it is naive.
    :return: An aware :py:class:`datetime.datetime` instance.
    """
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    if not isinstance(tzinfo, datetime.tzinfo):
        raise TypeError("tzinfo must be a datetime.tzinfo instance")
    if dt.tzinfo is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check for typical Matrix API path prefix
        path = getattr(request, "path", None)
        if path and path.startswith("/_matrix"):
            return True

        # Check for JSON content type commonly used by Matrix
        if hasattr(request, "META"):
            content_type = request.META.get("CONTENT_TYPE", "")
            if content_type.lower().startswith("application/json"):
                return True

            # Some Matrix clients may set a custom header
            if request.META.get("HTTP_X_MATRIX_REQUEST"):
                return True

        return False
    except Exception:
        # In case of any unexpected attribute errors or other issues,
        # conservatively return False rather than raising.
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    try:
        if not isinstance(dt, datetime.datetime):
            raise TypeError("dt must be a datetime.datetime instance")
        # If the datetime is naive, assume UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        # Convert to UTC and format as ISO 8601 without microseconds
        return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as exc:
        raise ValueError(f"Invalid datetime value: {exc}") from exc

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        # Split the text into words while preserving whitespace
        parts = text.split()
        result_parts = []
        for part in parts:
            # Detect simple http/https URLs
            if part.startswith('http://') or part.startswith('https://'):
                # Separate any trailing punctuation from the URL
                url = part
                trailing = ''
                while url and url[-1] in '.,;!?)':
                    trailing = url[-1] + trailing
                    url = url[:-1]
                # Build the link with attributes
                link = f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>{trailing}'
                result_parts.append(link)
            else:
                result_parts.append(part)
        return ' '.join(result_parts)
    except Exception:
        # If anything goes wrong, return the original text unchanged
        return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            raise TypeError("'tag' must be a string")
        tag = tag.strip()
        if not tag:
            return False
        # Tag must consist of letters, digits, hyphens, or underscores
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        if not pattern.match(tag):
            return False
        # Optional length constraint (e.g., max 30 characters)
        if len(tag) > 30:
            return False
        return True
    except Exception:
        # In case of unexpected errors, consider the tag invalid
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    try:
        for child in node:
            tag = child.tag
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception as exc:
        raise ValueError(f"Failed to iterate children of node {node!r}: {exc}") from exc
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    # Normalize base URL by stripping any trailing slash
    base = url.rstrip("/")
    # Handle custom document path
    if document_path is not None:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        if document_path == "":
            document_path = None
    if document_path:
        # Ensure the path starts with a slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        # Remove any trailing slash from the custom path
        nodeinfo_path = document_path.rstrip("/")
    else:
        # Default NodeInfo document path
        nodeinfo_path = "/.well-known/nodeinfo/1.0"
    href = base + nodeinfo_path
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    try:
        # Try JSON first
        data = json.loads(document)
        subject = data.get("subject")
        if subject:
            result["subject"] = subject
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel")
            href = link.get("href")
            if not rel or not href:
                continue
            if rel == "self":
                result["self_url"] = href
            elif rel == "hcard":
                result["hcard_url"] = href
            elif rel == "avatar":
                result["avatar_url"] = href
            else:
                result.setdefault("links", []).append({"rel": rel, "href": href})
        return result
    except Exception:
        # Fallback to XRD (XML)
        try:
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ET.fromstring(document)
            subject_el = root.find("xrd:Subject", ns)
            if subject_el is not None and subject_el.text:
                result["subject"] = subject_el.text
            for link_el in root.findall("xrd:Link", ns):
                rel = link_el.get("rel")
                href = link_el.get("href")
                if not rel or not href:
                    continue
                if rel == "self":
                    result["self_url"] = href
                elif rel == "hcard":
                    result["hcard_url"] = href
                elif rel == "avatar":
                    result["avatar_url"] = href
                else:
                    result.setdefault("links", []).append({"rel": rel, "href": href})
            return result
        except Exception as e:
            logger.warning("parse_diaspora_webfinger: failed to parse document: %s", e)
            return None
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        user, host = handle.split("@", 1)
    except ValueError:
        return None

    import urllib.request
    import urllib.parse
    import urllib.error

    url = f"https://{host}/.well-known/webfinger?resource=acct:{urllib.parse.quote(handle)}"
    try:
        with urllib.request.urlopen(url) as resp:
            return resp.read().decode("utf-8")
    except (urllib.error.URLError, urllib.error.HTTPError, Exception):
        return None

