        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception:
        return None
    return xrd

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import re

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple, set)):
        dirs = list(settings_dirs)
    else:
        # If not a valid type, return empty list
        return []

    # Normalize spec_option
    if spec_option is None:
        patterns = [None]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    elif isinstance(spec_option, (list, tuple, set)):
        patterns = list(spec_option)
    else:
        # Unsupported spec_option type
        patterns = [None]

    matched_files = []

    for dir_path in dirs:
        try:
            for fname in os.listdir(dir_path):
                full_path = os.path.join(dir_path, fname)
                if not os.path.isfile(full_path):
                    continue

                matched = False
                for pat in patterns:
                    if pat is None:
                        matched = True
                        break
                    # If pattern looks like a regex (contains regex meta chars)
                    if any(ch in pat for ch in ".^$*+?{}[]|()"):
                        try:
                            if re.search(pat, fname):
                                matched = True
                                break
                        except re.error:
                            # Invalid regex, skip this pattern
                            continue
                    else:
                        # Treat as simple suffix match
                        if fname.endswith(pat):
                            matched = True
                            break

                if matched:
                    matched_files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(matched_files)

def workspace_manager(cls):
    """Gets the workspace manager. """
    try:
        if not hasattr(cls, "_workspace_manager"):
            cls._workspace_manager = WorkspaceManager()
        return cls._workspace_manager
    except Exception as e:
        raise RuntimeError("Failed to get workspace manager") from e

def plugins_manager(cls):
    """Gets the plugin manager. """
    try:
        if not hasattr(cls, "_plugin_manager"):
            cls._plugin_manager = {}
        return cls._plugin_manager
    except Exception as exc:
        raise RuntimeError(f"Failed to get plugin manager: {exc}")

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as fnf:
        raise IRValidatorException(f"File not found: {yaml_file}") from fnf
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")
    required = getattr(cls, 'required_fields', [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _merge(parser_name, visited):
        if parser_name in visited:
            cycle = ' -> '.join(list(visited) + [parser_name])
            raise ValueError(f"Circular include detected: {cycle}")
        visited.add(parser_name)
        parser = parser_dict.get(parser_name)
        if parser is None:
            raise KeyError(f"Parser '{parser_name}' not found in parser_dict.")
        include = parser.get('include')
        if include:
            if isinstance(include, str):
                include = [include]
            for inc_name in include:
                if inc_name not in parser_dict:
                    raise KeyError(f"Included parser '{inc_name}' not found for '{parser_name}'.")
                _merge(inc_name, visited)
                inc_parser = parser_dict[inc_name]
                for k, v in inc_parser.items():
                    if k not in parser:
                        parser[k] = v
            parser.pop('include', None)
        visited.remove(parser_name)

    for pname in list(parser_dict.keys()):
        _merge(pname, set())

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Attempt to fetch value from spec if available
        val = None
        if self.spec is not None:
            try:
                # Support dict-like or object with get method
                if hasattr(self.spec, "get"):
                    val = self.spec.get(arg.name)
                else:
                    val = getattr(self.spec, arg.name, None)
            except Exception:
                val = None

        # If spec provided a value, use it; otherwise fall back to default
        if val is not None:
            defaults[arg.name] = val
        else:
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # Handle nested dictionary options
        if isinstance(arg, DictOption) and arg.scheme:
            try:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested
            except Exception as exc:
                # If nested scheme fails, propagate a clear error
                raise errors.InvalidSpecError(
                    f"Failed to resolve defaults for nested scheme '{arg.name}': {exc}"
                ) from exc

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Mapping of deprecated argument names to their current replacements.
    # Add or modify entries as needed for your application.
    return {
        "old_option": "new_option",
        "legacy_flag": "modern_flag",
    }

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")

    # Retrieve the internal mapping of command names to option specs
    options_map = getattr(self, "_command_options", None)
    if options_map is None:
        raise AttributeError("The object does not contain a '_command_options' mapping")

    # Attempt to fetch the options for the requested command
    try:
        options = options_map[command_name]
    except KeyError:
        available = ", ".join(sorted(options_map.keys()))
        raise KeyError(
            f"Unknown command '{command_name}'. "
            f"Available commands: {available}"
        )

    # Ensure the returned value is a list (or can be converted to one)
    if isinstance(options, (list, tuple)):
        return list(options)
    else:
        # If the stored value is a single option spec, wrap it in a list
        return [options]

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to values")

    required = []

    for opt in options_spec:
        # Support both dicts and objects
        opt_name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
        if opt_name is None:
            continue

        # Only consider options for the given command
        opt_cmd = opt.get('command') if isinstance(opt, dict) else getattr(opt, 'command', None)
        if opt_cmd not in (None, command_name):
            continue

        cond = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        if cond is None:
            continue

        try:
            if callable(cond):
                # Callable receives the args dict
                match = bool(cond(args))
            elif isinstance(cond, str):
                # Evaluate string expression with args in local namespace
                match = bool(eval(cond, {}, {'args': args}))
            else:
                raise TypeError(f"required_when for option '{opt_name}' must be a callable or string")
        except Exception as exc:
            raise ValueError(f"Error evaluating required_when for option '{opt_name}': {exc}") from exc

        if match:
            required.append(opt_name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict (got %s)" % type(args).__name__)

    spec = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        arg_spec = spec.get(arg_name, {})
        max_len = arg_spec.get('length')
        if max_len is None:
            continue
        if not isinstance(max_len, int):
            raise TypeError(
                "length for argument '%s' must be an int (got %s)"
                % (arg_name, type(max_len).__name__)
            )
        if max_len < 0:
            raise ValueError(
                "length for argument '%s' must be non-negative (got %d)"
                % (arg_name, max_len)
            )
        try:
            val_len = len(value)
        except TypeError:
            # value has no length; skip validation
            continue
        if val_len > max_len:
            raise ValueError(
                "argument '%s' length %d exceeds maximum %d"
                % (arg_name, val_len, max_len)
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML configuration.
    arg_defs = self.parsed_yaml.get('args', {})
    # Normalise the argument definitions to an iterable of (name, attrs) pairs.
    if isinstance(arg_defs, dict):
        items = arg_defs.items()
    elif isinstance(arg_defs, list):
        # Each list item is expected to be a single-key dict.
        items = ((list(item.items())[0]) for item in arg_defs)
    else:
        # Unsupported format; nothing to validate.
        return

    for arg_name, arg_attrs in items:
        # Only validate arguments that have a 'choices' specification.
        if isinstance(arg_attrs, dict) and 'choices' in arg_attrs:
            # Skip validation if the argument was not supplied.
            if arg_name not in args:
                continue
            value = args[arg_name]
            # If the value is not one of the allowed choices, raise an error.
            if value not in arg_attrs['choices']:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {arg_attrs['choices']!r}."
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure that min and max attributes exist and are valid
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError("minimum value must be less than or equal to maximum value")

    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of values")

    # Validate each value
    for idx, value in enumerate(iterator):
        # Skip None values if desired; here we treat None as invalid
        if value is None:
            raise ValueError(f"argument at position {idx} is None, which is not allowed")

        # Compare with minimum
        if min_val is not None:
            try:
                if value < min_val:
                    raise ValueError(
                        f"argument at position {idx} ({value}) is less than minimum {min_val}"
                    )
            except TypeError:
                raise TypeError(
                    f"argument at position {idx} ({value}) is not comparable to minimum {min_val}"
                )

        # Compare with maximum
        if max_val is not None:
            try:
                if value > max_val:
                    raise ValueError(
                        f"argument at position {idx} ({value}) is greater than maximum {max_val}"
                    )
            except TypeError:
                raise TypeError(
                    f"argument at position {idx} ({value}) is not comparable to maximum {max_val}"
                )

    # If all values pass, return the original iterable
    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # Build a unique, pythonic type name
    full_type_name = f"{subcommand}_{type_name}".replace("-", "_").replace(" ", "_")

    # Define the parsing function that will be used as the argparse type
    def _complex_type(value):
        """
        Parse the raw string value into a structured object based on spec_option.
        """
        try:
            # If a custom parser is provided, use it
            custom_parser = spec_option.get("parser")
            if custom_parser and callable(custom_parser):
                return custom_parser(value)

            # If fields are specified, parse key=value pairs
            fields = spec_option.get("fields")
            if fields:
                if not isinstance(value, str):
                    raise ValueError("Expected string input for complex type")
                parts = [p.strip() for p in value.split(",") if p.strip()]
                result = {}
                for part in parts:
                    if "=" not in part:
                        raise ValueError(f"Invalid field format: '{part}'")
                    key, val = part.split("=", 1)
                    key = key.strip()
                    val = val.strip()
                    if key not in fields:
                        raise ValueError(f"Unexpected field '{key}'")
                    # Cast to the specified type if provided
                    cast_type = spec_option.get("field_types", {}).get(key, str)
                    try:
                        result[key] = cast_type(val)
                    except Exception as e:
                        raise ValueError(f"Failed to cast field '{key}' to {cast_type}: {e}")
                return result

            # Default behaviour: return the raw string or split by comma
            if isinstance(value, str):
                return [v.strip() for v in value.split(",") if v.strip()]
            return value
        except Exception as exc:
            raise ValueError(f"Error parsing option '{option_name}': {exc}") from exc

    # Attach metadata to the function for introspection
    _complex_type.__name__ = full_type_name
    _complex_type.__doc__ = spec_option.get("help",
                                            f"Complex type for option '{option_name}'")

    return _complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Validate input
    if args is None:
        return {}, {}
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, list):
        try:
            items = dict(args).items()
        except Exception as exc:
            raise ValueError("args list must contain key/value pairs") from exc
    else:
        raise TypeError("args must be a dict or a list of key/value pairs")

    control_args = {}
    nested_args = {}
    for key, value in items:
        if not isinstance(key, str):
            # Skip non-string keys
            continue
        if key.startswith("control_"):
            control_args[key] = value
        else:
            # Treat all other keys as nested (including custom)
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple of mappings")
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)):
                # allow list/tuple of key-value pairs
                for kv in item:
                    if isinstance(kv, (list, tuple)) and len(kv) == 2:
                        key, value = kv
                        vars_dict[key] = value
                    else:
                        raise ValueError("Each item in extra_vars must be a dict or a list/tuple of key-value pairs")
            else:
                raise ValueError("Each item in extra_vars must be a dict or a list/tuple of key-value pairs")
        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic validation
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")
    if not isinstance(playbook_path, str) or not playbook_path:
        raise TypeError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Prepare the base command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose level must be non-negative")
            cmd.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            # Accept strings like "-v", "-vvv", etc.
            if not verbose.startswith("-"):
                raise ValueError("verbose string must start with '-'")
            cmd.append(verbose)
        else:
            raise TypeError("verbose must be int or str")

    # Handle ansible_args
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
                # if False, skip adding the flag
            else:
                cmd.append(f"--{key}={value}")

    # Handle extra_vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        # Convert dict to JSON string for --extra-vars
        import json
        json_str = json.dumps(extra_vars)
        cmd.extend(["--extra-vars", json_str])

    # Logging the command (use the plugin's logger if available)
    logger = getattr(ir_plugin, "logger", logging.getLogger(__name__))
    logger.debug("Executing ansible-playbook command: %s", " ".join(cmd))

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Failed to execute ansible-playbook: {e}") from e

    # Check for errors
    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook failed with return code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        raise RuntimeError(error_msg)

    # Return the stdout output
    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser for the given command name
    try:
        parser = self.parsers[parser_name]
    except KeyError as exc:
        raise KeyError(f"Parser '{parser_name}' not found in parsers registry.") from exc

    # Iterate over all actions defined in the parser
    for action in parser._actions:
        dest = action.dest
        if dest not in values_dict:
            continue

        raw_value = values_dict[dest]

        # If the action defines a type, use it to cast the value
        if action.type is not None:
            try:
                values_dict[dest] = action.type(raw_value)
            except Exception as exc:
                raise ValueError(
                    f"Could not convert argument '{dest}' to {action.type.__name__}: {exc}"
                ) from exc
            continue

        # Handle boolean flags (store_true/store_false)
        if action.const is not None:
            if isinstance(raw_value, str):
                lowered = raw_value.lower()
                if lowered in ("true", "1", "yes", "y"):
                    values_dict[dest] = True
                elif lowered in ("false", "0", "no", "n"):
                    values_dict[dest] = False
                else:
                    values_dict[dest] = bool(raw_value)
            else:
                values_dict[dest] = bool(raw_value)
            continue

        # For actions without a type or const, leave the value as a string
        # (no conversion needed)
        continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        if not os.path.isdir(plugin_dir):
            return {}

        # Locate the plugin spec file (JSON or YAML)
        spec_file = None
        for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
            path = os.path.join(plugin_dir, fname)
            if os.path.isfile(path):
                spec_file = path
                break

        if spec_file is None:
            return {}

        # Load the spec file
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    # If YAML parsing fails, return empty dict
                    return {}

        # Flatten nested dictionaries
        flat = {}

        def _flatten(obj, parent_key=""):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    new_key = f"{parent_key}.{k}" if parent_key else k
                    _flatten(v, new_key)
            else:
                flat[parent_key] = obj

        _flatten(data)
        return flat
    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}
